import csv, ast
from collections import Counter,defaultdict
valid=[939,961,561,146,447,304,956,964,959,123,946,385,987,148,387,452,867,978,253,590,900]
pay={939:500,961:500,561:500,146:500,447:500,304:300,956:300,964:300,959:300,123:290,946:290,385:290,987:290,148:290,387:140,452:140,867:140,978:140,253:160,590:160,900:160}

def parse(s):
    try:
        v=ast.literal_eval(s)
        if isinstance(v,(list,tuple)):
            return [int(x) for x in v]
    except Exception:
        toks=[x.strip() for x in s.replace('[','').replace(']','').split(',') if x.strip()]
        if toks and all(t.isdigit() for t in toks):
            return [int(t) for t in toks]
    return None

def hamming(a,b):
    a=str(a); b=str(b)
    if len(a)!=len(b):
        return 999
    return sum(x!=y for x,y in zip(a,b))

def closest(t):
    best=sorted((hamming(t,v), abs(t-v), v) for v in valid)[0]
    return best[2], best[:2]

with open('/app/dataset/timesheet.csv', newline='', encoding='utf-8') as f:
    rows=list(csv.DictReader(f))
count=0
samples=[]
for r in rows:
    tasks=parse(r['performed_tasks'])
    if tasks is None:
        continue
    fixed=[]
    info=[]
    for t in tasks:
        if t in pay:
            fixed.append(t)
            info.append((t,t,pay[t]))
        else:
            c,meta=closest(t)
            fixed.append(c)
            info.append((t,c,pay[c],meta))
    s=sum(pay[t] for t in fixed)
    b=int(float(r['bonus']))
    if s==b:
        count+=1
    elif len(samples)<50 and any(orig!=corr for orig,corr,*_ in info):
        samples.append((r['id'], tasks, info, b, s))
print('rows matching bonus after closest-ID correction', count, 'of', len(rows))
for sample in samples[:50]:
    print(sample)
