valid_ids={r['PESEL'] for r in employees}
valid_id_list=sorted(valid_ids)
rate={r['PESEL']:int(float(r['hourly_rate'])) for r in employees}
pay={int(r['task_id']):int(float(r['pay_per_completion'])) for r in tasks}
valid_task_ids=sorted(pay)

def closest_id(bad):
    return min(valid_id_list, key=lambda eid:(sum(a!=b for a,b in zip(bad,eid))+abs(len(bad)-len(eid)), abs(int(bad)-int(eid)), eid))

def cdate(s):
    y,m,d=map(int,s.split('-'))
    d=min(d, calendar.monthrange(y,m)[1])
    return date(y,m,d)

def parse_tasks(s):
    try:
        v=ast.literal_eval(s)
        if isinstance(v,(list,tuple)):
            return [int(x) for x in v]
    except Exception:
        toks=[x.strip() for x in s.replace('[','').replace(']','').split(',') if x.strip()]
        if toks and all(t.isdigit() for t in toks):
            return [int(t) for t in toks]
    return []

def ham(a,b):
    a=str(a); b=str(b)
    return sum(x!=y for x,y in zip(a,b)) if len(a)==len(b) else 999

def fix_task(t):
    if t in pay:
        return t
    return min(valid_task_ids, key=lambda v:(ham(t,v), abs(t-v), v))

# drop invalid employee rows when matching valid row exists for mapped id on date/facility/hours
valid_key_rows={(r['employee_id'], r['date'], r['facility_id'], r['hours_worked']) for r in rows if r['employee_id'] in valid_ids}
filtered=[]
for r in rows:
    if r['employee_id'] not in valid_ids:
        mapped=closest_id(r['employee_id'])
        if (mapped, r['date'], r['facility_id'], r['hours_worked']) in valid_key_rows:
            continue
        r=r.copy(); r['employee_id']=mapped
    filtered.append(r)
# dedupe exact rows ignoring id
seen=set(); dedup=[]
for r in filtered:
    key=tuple((k,v) for k,v in r.items() if k!='id')
    if key in seen:
        continue
    seen.add(key)
    dedup.append(r)

# anchor weekday from earliest corrected date
all_dates=[cdate(r['date']) for r in dedup]
anchor_wd=min(all_dates).weekday()
months=[]
cur=date(min(all_dates).year, min(all_dates).month, 1)
last=date(max(all_dates).year, max(all_dates).month, 1)
while cur<=last:
    d=cur
    while d.weekday()!=anchor_wd:
        d += timedelta(days=1)
    months.append(d)
    if cur.month==12:
        cur=date(cur.year+1,1,1)
    else:
        cur=date(cur.year,cur.month+1,1)

def period_start(dt):
    for s in reversed(months):
        if dt>=s:
            return s
    return months[0]

records=[]
by_emp=defaultdict(list)
for r in dedup:
    rr=r.copy()
    rr['cdate']=cdate(r['date'])
    rr['salary']=int(float(r['salary_amount']))
    rr['tasks_fixed']=[fix_task(t) for t in parse_tasks(r['performed_tasks'])]
    rr['bonus_fixed']=sum(pay[t] for t in rr['tasks_fixed'])
    by_emp[rr['employee_id']].append(rr)

kept=[]
for eid,recs in by_emp.items():
    recs.sort(key=lambda r:(r['cdate'], r['salary'], int(r['id'])))
    prev=None
    for r in recs:
        sal=r['salary']
        if prev is None or sal<prev:
            delta=sal
        else:
            delta=sal-prev
        prev=sal
        if delta<=0:
            continue
        kept.append((eid, r['cdate'], period_start(r['cdate']), delta, r['bonus_fixed'], r['id'], r['facility_id'], r['hours_worked'], r['performed_tasks'], r['bonus']))

# aggregate
periods=months
res={eid:{p:0 for p in periods} for eid in valid_id_list}
rows_per=Counter()
for eid,dt,ps,delta,bonus,*_ in kept:
    res[eid][ps]+=delta+bonus
    rows_per[(eid,ps)] += 1
print('period starts', periods)
print('kept rows', len(kept))
print('employees missing periods count:')
missing=[]
for eid in valid_id_list:
    miss=[p for p in periods if rows_per[(eid,p)]==0]
    if miss:
        missing.append((eid, miss))
print(len(missing))
print(missing[:30])
print('sample outputs:')
for eid in valid_id_list[:10]:
    print(eid, [res[eid][p] for p in periods], [rows_per[(eid,p)] for p in periods])
